begin;

select plan(260);

-- Aide : exécute une écriture avec le rôle courant, renvoie le nombre de lignes touchées (ou « ERR sqlstate »),
-- puis annule l'écriture (sous-transaction).
create function public.tap_try(q text) returns text language plpgsql as $f$
declare n int;
begin
  begin
    execute q;
    get diagnostics n = row_count;
    raise exception 'tap_rollback';
  exception when raise_exception then
    if sqlerrm <> 'tap_rollback' then raise; end if;
    return n::text;
  when others then
    return 'ERR ' || sqlstate;
  end;
end $f$;

