select is((select count(*) from pg_policies where schemaname = 'public' and tablename in ('bug_reports','characters','group_journal_entries','group_members','group_notes','groups','notification_preferences','user_push_tokens') and (coalesce(qual,'') || coalesce(with_check,'')) ~ '(?<!SELECT )auth\.uid\(\)')::int, 0, 'aucun auth.uid() nu');
