select is((select count(*) from pg_policies where schemaname = 'public' and tablename in ('bug_reports','characters','group_journal_entries','group_members','group_notes','groups','notification_preferences','user_push_tokens'))::int, 30, '30 politiques au total (aucune ajoutée ni retirée)');
select is((select count(*) from pg_policies where schemaname = 'public' and tablename in ('bug_reports','characters','group_journal_entries','group_members','group_notes','groups','notification_preferences','user_push_tokens') and roles <> '{authenticated}')::int, 0, 'tous les rôles inchangés (authenticated)');
select is((select string_agg(cmd, ',' order by cmd) from pg_policies where schemaname = 'public' and tablename = 'characters'), 'DELETE,INSERT,SELECT,SELECT,SELECT,UPDATE', 'characters : commandes inchangées');

